// Which .gpx files are in the route folder, newest answer every time.
//
// The add-on's view of Home Assistant's config directory moved: older ones
// mount it at /config, current ones at /homeassistant. Rather than hard-code
// the guess and fail obscurely, try both and say which was used.
const dirs = ['/homeassistant/www/treadmill/routes',
              '/config/www/treadmill/routes'];
const dir = dirs.find(function (d) {
    try { return fs.statSync(d).isDirectory(); } catch (e) { return false; }
});
if (!dir) {
    node.error('none of these are a directory: ' + dirs.join(' '), msg);
    node.status({fill: 'red', shape: 'dot', text: 'no route folder'});
    return null;
}
const names = fs.readdirSync(dir)
    .filter(function (f) { return /\.gpx$/i.test(f); })
    .sort();
// A bare JSON array of filenames, which is what the console reads. Never an
// empty array on error: the console treats an empty listing as a failure and
// keeps its cache, which is right, but there is no reason to send one.
msg.payload = JSON.stringify(names);
msg.filename = dir + '/index.json';
node.status({fill: 'green', shape: 'dot', text: names.length + ' route(s)'});
return msg;

